// Signs the GET request. GET has no body, so the empty string is what is signed.
const crypto = require('crypto');
const secret = $env.LENDLOOP_SHARED_SECRET;
if (!secret) throw new Error('LENDLOOP_SHARED_SECRET is not set on the n8n container');

const timestamp = String(Math.floor(Date.now() / 1000));
const signature = crypto.createHmac('sha256', secret).update(`${timestamp}.`).digest('hex');

return [{ json: { timestamp, signature } }];

// Turns the response into one item per loan, each with its own signatures and
// idempotency key. The claim is written first so a retry cannot create a second
// reminder; the confirmation is sent only after the reminder itself succeeds.
const crypto = require('crypto');
const secret = $env.LENDLOOP_SHARED_SECRET;

const response = $input.first().json;
const loans = Array.isArray(response.loans) ? response.loans : [];
const today = new Date().toISOString().slice(0, 10);

const output = [];

for (const loan of loans) {
  if (!loan.loanId || !loan.daysOverdue || loan.daysOverdue <= 0) continue;

  const dueDate = new Date(loan.dueDate).toISOString().slice(0, 10);
  const message = `Your loan of ${loan.toolName} was due ${dueDate} and is ${loan.daysOverdue} day(s) late. Please return it to your neighbor.`;

  const body = JSON.stringify({
    loanId: loan.loanId,
    channel: 'mock',
    detail: `Overdue reminder for ${loan.toolName} (${loan.daysOverdue}d late)`,
  });

  const timestamp = String(Math.floor(Date.now() / 1000));
  const signature = crypto.createHmac('sha256', secret).update(`${timestamp}.${body}`).digest('hex');

  // The confirmation is a separate signed request with the same idempotency key.
  const confirmBody = JSON.stringify({ loanId: loan.loanId });
  const confirmTimestamp = String(Math.floor(Date.now() / 1000));
  const confirmSignature = crypto
    .createHmac('sha256', secret)
    .update(`${confirmTimestamp}.${confirmBody}`)
    .digest('hex');

  output.push({
    json: {
      loanId: loan.loanId,
      body,
      timestamp,
      signature,
      confirmBody,
      confirmTimestamp,
      confirmSignature,
      // Null, not a placeholder, so a missing address fails loudly in the send step.
      recipientEmail: loan.borrowerEmail ?? null,
      // Derived from data, so a retried run and a duplicate schedule run produce
      // the same key and the claim collapses to one record.
      idempotencyKey: `reminder:${loan.loanId}:${loan.dueDate}:${today}`,
      message,
    },
  });
}

return output;

// Sends only for reminders this run actually claimed. A duplicate claim means a
// previous run already handled it, so re-running the schedule is safe.
//
// The build item is matched by loanId, not by array position, so a rejected or
// reordered HTTP response cannot send one borrower's message to another.
const claims = $input.all();
const originals = $('Build signed reminders').all().map((item) => item.json);

const output = [];

for (const item of claims) {
  const claim = item.json ?? {};
  const original = originals.find((entry) => entry.loanId === claim.loanId);

  if (!original) {
    throw new Error(`No signed reminder matches claim ${claim.loanId ?? 'unknown'}`);
  }
  if (claim.ok !== true) {
    throw new Error(`Reminder claim was rejected for loan ${claim.loanId}`);
  }
  // A duplicate that was never confirmed means an earlier run claimed the
  // reminder but did not finish. Retry the send; only a confirmed duplicate is
  // skipped, so a stuck claim cannot silence the reminder.
  if (claim.duplicate === true && claim.confirmed === true) continue;

  if (!original.recipientEmail) {
    // Throwing (not returning) fails the execution, which invokes the error
    // workflow. A reminder that cannot be delivered must be visible.
    throw new Error(`No recipient email for loan ${claim.loanId}`);
  }

  // The assignment allows a logged mock instead of real email. Swap this for an
  // Email/Slack node; the claim -> send -> confirm protocol around it is unchanged.
  console.log(
    `[LENDLOOP MOCK] to=${original.recipientEmail} subject=Overdue: ${original.message}`,
  );

  output.push({
    json: {
      loanId: original.loanId,
      recipientEmail: original.recipientEmail,
      body: original.confirmBody,
      timestamp: original.confirmTimestamp,
      signature: original.confirmSignature,
      idempotencyKey: original.idempotencyKey,
    },
  });
}

return output;
